// Find the earliest Friday the 13th in the proleptic Gregorian calendar (starting 0001-01-01)
// and count all Friday the 13ths in a full 400-year cycle.

// Earliest Friday the 13th
var date = new DateTime(1, 1, 13);
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd}");

// Count in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
var start = new DateTime(1, 1, 13);
var end = new DateTime(401, 1, 1);

while (start < end)
{
    if (start.DayOfWeek == DayOfWeek.Friday)
        count++;
    start = start.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// Bonus: which day-of-week is most common for the 13th?
var dayCounts = new int[7];
var d = new DateTime(1, 1, 13);
while (d < end)
{
    dayCounts[(int)d.DayOfWeek]++;
    d = d.AddMonths(1);
}

Console.WriteLine("\n13th falls on each day of week (400-year cycle):");
foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-10}: {dayCounts[(int)dow]}");
EOF
dotnet /tmp/friday13.cs

